function chunk(list, size) {
  var chunks = [];
  for (var i = 0; i < list.length; i += size) {
    chunks.push(list.slice(i, i + size));
  }
  return chunks;
}

console.log(chunk(["a", "b", "c", "d", "e"], 2));
